def destroy
  @status = Status.where(account: current_account).find(params[:id])
  authorize @status, :destroy?
  @status.discard_with_reblogs
  StatusPin.find_by(status: @status)&.destroy
  @status.account.statuses_count = @status.account.statuses_count - 1
  RemovalWorker.perform_async(@status.id, { 'redraft' => !truthy_param?(:delete_media) })
  render json: json
end

def update
  @media_attachment.update!(updateable_media_attachment_params)
end
def set_media_attachment
  @media_attachment = current_account.media_attachments.where(status_id: nil).find(params[:id])
end

def destroy
  @media_attachment = current_account.media_attachments.find(params[:id])
  return render json: in_usage_error, status: 422 unless @media_attachment.status_id.nil?
  @media_attachment.destroy
  render_empty
end

def set_account
  @account = ResolveAccountService.new.call(params[:acct], skip_webfinger: true) || raise(ActiveRecord::RecordNotFound)
end

def call(account, target_account)
  return unless account.blocking?(target_account)
  unblock = account.unblock!(target_account)
  unblock
end

def call(account, target_account)
  return unless account.muting?(target_account)
  account.unmute!(target_account)
end

if params[:comment].blank?
  current_account.account_notes.find_by(target_account: @account)&.destroy
else
  @note = current_account.account_notes.find_or_initialize_by(target_account: @account)
  @note.comment = params[:comment]
  @note.save! if @note.changed?
end

def create
  @domain_block = DomainBlock.new(resource_params)
  existing_domain_block = resource_params[:domain].present? ? DomainBlock.rule_for(resource_params[:domain]) : nil
  return render json: ..., status: 422 if conflicts_with_existing_block?(@domain_block, existing_domain_block)
  @domain_block.save!
  DomainBlockWorker.perform_async(@domain_block.id)
  log_action :create, @domain_block
end
